local config = {
  ui_story_31170401_1_dialog_content = "¿Ves, Vice? Te dije que nuestro Navegante no se veía bien hoy.",
  ui_story_31170401_2_dialog_content = "Cara pálida, labios agrietados... Incluso el cabello de PlayerName se ve desordenado.",
  ui_story_31170401_3_dialog_content = "Tienes toda la razón. Han pasado días desde que el Navegador comió adecuadamente.",
  ui_story_31170401_4_dialog_content = "Hoy no fue diferente... El pan que sirvieron esta mañana, PlayerName ni siquiera le dio un mordisco.",
  ui_story_31170401_5_dialog_content = "Es cierto, últimamente no he tenido mucho apetito... También me he sentido muy débil por alguna razón...",
  ui_story_31170401_6_dialog_content = "Déjame ver.",
  ui_story_31170401_7_dialog_content = "Sin fiebre.",
  ui_story_31170401_8_dialog_content = "Sr. Gram...",
  ui_story_31170401_9_dialog_content = "Solo \"Gram\" servirá.",
  ui_story_31170401_10_dialog_content = "G-Gram... ¿Puedes soltar mis párpados, por favor?",
  ui_story_31170401_11_dialog_content = "El blanco de tus ojos tampoco se ve muy bien... ¿Cómo has estado durmiendo últimamente?",
  ui_story_31170401_12_dialog_content = "Recuerdo que tus luces estaban encendidas hasta muy tarde anoche, Navegante.",
  ui_story_31170401_13_dialog_content = "¿A qué hora te fuiste a la cama anoche?",
  ui_story_31170401_14_dialog_content = "No puedo recordar... Solo recuerdo acostarme por un segundo, y al siguiente segundo ustedes dos me estaban llamando.",
  ui_story_31170401_15_dialog_content = "Diría que dormí dos, tres horas, ¿quizás?",
  ui_story_31170401_16_dialog_content = "Pero está bien, ¡confía en mí! Me he acostumbrado en estos últimos días. Solo me sentí un poco cansada cuando me levanté de la cama, eso es todo.",
  ui_story_31170401_17_dialog_content = "¿Cuánto tiempo llevas manteniendo este tipo de rutina?",
  ui_story_31170401_18_dialog_content = "Aproximadamente una semana.",
  ui_story_31170401_19_dialog_content = "Eso fue aproximadamente cuando también comenzaste a perder el apetito.",
  ui_story_31170401_20_dialog_content = "Entendido. De hecho, he visto esto antes. Lo llamamos <color=#FFB400>Trastorno de la Función Corporal</color>, o TFC.",
  ui_story_31170401_21_dialog_content = "Muchos soldados nuevos lo contraen. Afortunadamente, resulta que tengo la <color=#FFB400>cura</color>.",
  ui_story_31170401_22_dialog_content = "Vice, parece que PlayerName no podrá trabajar. ¿Qué pasa con el Coloso?",
  ui_story_31170401_23_dialog_content = "Manejaré las responsabilidades del Navegante por el momento.",
  ui_story_31170401_24_dialog_content = "¿Qué... tipo de cura? ¿Es amargo?",
  ui_story_31170401_25_dialog_content = "Para nada, pero puede ser un poco agotador. Veamos si puedes manejarlo.",
  ui_story_31170401_26_option_content = "¿Cobrando impuestos...?",
  ui_story_31170401_27_dialog_content = "¿Cómo puede ser agotador tomar medicina? ¿Tengo que comer una pastilla ridículamente grande o algo así?",
  ui_story_31170401_28_dialog_content = "Ojalá fuera tan fácil...",
  ui_story_31170401_29_dialog_content = "Esta cura afectará cada nervio y músculo de tu cuerpo, aumentando drásticamente la circulación sanguínea. Te sentirás como una persona completamente nueva después de tomarla.",
  ui_story_31170401_30_option_content = "¿Manejarlo...?",
  ui_story_31170401_31_dialog_content = "No es amargo, pero ¿por qué aún suena tan horrible?",
  ui_story_31170401_32_dialog_content = "¿Es realmente picante como el wasabi o algo así?",
  ui_story_31170401_33_dialog_content = "No es picante en lo más mínimo, aunque definitivamente te hará sudar como nunca antes.",
  ui_story_31170401_34_dialog_content = "En aquellos días, solía tomarlo todo el tiempo... Así que puedes confiar en mí cuando te digo que hace maravillas en el cuerpo.",
  ui_story_31170401_35_dialog_content = "Pero primero, necesito ver qué tan desordenadas se han vuelto tus funciones corporales.",
  ui_story_31170401_36_dialog_content = "Una prueba simple será suficiente.",
  ui_story_31170401_37_dialog_content = "¿Qué tipo de prueba?",
  ui_story_31170401_38_dialog_content = "¡Oh, en realidad podemos hacer todo tipo de pruebas! Pruebas de resistencia, pruebas de coordinación del tren inferior, pruebas de equilibrio, pruebas de fuerza en los brazos...",
  ui_story_31170401_39_dialog_content = "¡Haremos todos, uno tras otro!",
  ui_story_31170401_40_dialog_content = "Ahora bien, comencemos probando tu resistencia física haciéndote cargar agua.",
  ui_story_31170401_41_dialog_content = "Jaa... Jaa... Jaa...",
  ui_story_31170401_42_dialog_content = "¡Todavía te quedan dos baldes! ¡Vamos, sin detenernos!",
  ui_story_31170401_43_dialog_content = "Jaa... Jaa... Jaa...",
  ui_story_31170401_44_dialog_content = "Podemos probar la fuerza de tu brazo haciéndote cortar madera. El movimiento es bastante simple: levanta los brazos alto y luego baja con fuerza.",
  ui_story_31170401_45_dialog_content = "¡La clave es ser rápido y preciso!",
  ui_story_31170401_46_dialog_content = "¡Recuerda! Cada tronco debe dividirse en cuatro trozos del mismo tamaño.",
  ui_story_31170401_47_dialog_content = "Sí, señor...",
  ui_story_31170401_48_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_31170401_49_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_31170401_X49_dialog_content = "¡Lo siguiente es recoger guisantes!",
  ui_story_31170401_50_dialog_content = "Me duelen mucho los hombros...",
  ui_story_31170401_51_dialog_content = "Los niños de hoy en día realmente carecen de entrenamiento físico. ¡Mírate! Apenas hemos comenzado y tus brazos ya están temblando como las patas de un cervatillo.",
  ui_story_31170401_52_dialog_content = "¡No pares aún! Todavía tienes todos estos guisantes por recoger, ¡así que apúrate!",
  ui_story_31170401_53_dialog_content = "¡Pero hay demasiados de ellos! Mucho más de lo que una sola persona puede manejar...",
  ui_story_31170401_54_dialog_content = "El enemigo no tolerará todas tus quejas y excusas en una batalla real.",
  ui_story_31170401_55_dialog_content = "Tienes un punto, pero aún así...",
  ui_story_31170401_56_dialog_content = "Necesitas creer en ti mismo... ¡en tu tenacidad y perseverancia! Recuerda, diste tu palabra de que terminarías esto.",
  ui_story_31170401_57_dialog_content = "¡Ahora empieza a recoger y no dejes que se desperdicie nada!",
  ui_story_31170401_58_dialog_content = "*Sollozando* ¿Por qué tengo que hacer esto...?",
  ui_story_31170401_59_dialog_content = "No habría aceptado hacer sus pruebas si supiera que esto era lo que tenía que hacer... Simplemente no tenía apetito, eso es todo...",
  ui_story_31170401_60_dialog_content = "¡Todavía te quedan cinco pedazos de carne! ¡Sigue picando!",
  ui_story_31170401_61_dialog_content = "¿Qué tipo de prueba es esta, Gram?! ¡En este punto, solo me estás haciendo hacer tu trabajo, verdad?!",
  ui_story_31170401_62_dialog_content = "Llevar agua, cortar leña, recoger guisantes... ¿Y ahora, cortar carne? ¡Solo me estás usando como tu asistente!",
  ui_story_31170401_63_dialog_content = "Je... No cualquiera tiene lo necesario para ser mi asistente, ¿sabes?",
  ui_story_31170401_64_dialog_content = "Espera... ¿Qué es ese olor increíble...?",
  ui_story_31170401_65_dialog_content = "Gracias a todas las pruebas que hicimos recién, pude comprender completamente el estado actual de tu cuerpo y preparar esto para ti.",
  ui_story_31170401_66_dialog_content = "Aquí.",
  ui_story_31170401_67_dialog_content = "Arroz frito con carne y guisantes...?",
  ui_story_31170401_68_dialog_content = "(Gorjeo, gorgoteo)",
  ui_story_31170401_69_dialog_content = "Parece que recuperaste tu apetito. ¿Por qué no llevas esto a tu habitación...",
  ui_story_31170401_70_dialog_content = "*mascar*",
  ui_story_31170401_71_dialog_content = "¡Delicioso!",
  ui_story_31170401_72_dialog_content = "¿Cómo puede existir algo tan delicioso en el mundo?! ¡La carne está frita a la perfección!",
  ui_story_31170401_73_dialog_content = "La carne es grasosa pero no demasiado aceitosa, los guisantes están crujientes y sabrosos, y cada grano de arroz tostado se destaca perfectamente de los demás...",
  ui_story_31170401_74_dialog_content = "*mascar*",
  ui_story_31170401_75_dialog_content = "O simplemente puedes comerlo aquí. Parece que mis palabras no te están llegando en este momento, de todos modos.",
  ui_story_31170401_76_dialog_content = "*Tragar* ¿Cómo... Cómo puede algo saber tan increíble...?! *Munch*",
  ui_story_31170401_77_dialog_content = "Oye, más despacio. ¡No hables con la boca llena!",
  ui_story_31170401_78_dialog_content = "*Eructo*",
  ui_story_31170401_79_dialog_content = "¿De verdad hiciste ese arroz frito, Gram? *Eructo* No tenía idea... ¡de que fueras un maestro cocinero!",
  ui_story_31170401_80_dialog_content = "¡Jajaja! Pasé muchos años de mi vida militar trabajando en los comedores, ¡chico! Esto no fue nada, estoy seguro de que he alimentado a cada persona en las Ciudades Subterráneas al menos una vez.",
  ui_story_31170401_81_dialog_content = "Nunca lo hubiera imaginado... *Trago*",
  ui_story_31170401_82_dialog_content = "Ejem... Me alegra que te haya gustado, pero realmente no necesitas lamer el plato hasta dejarlo limpio.",
  ui_story_31170401_83_dialog_content = "¡Oh, cierto! ¿Cuándo debo tomar mi medicina, Gram?",
  ui_story_31170401_84_dialog_content = "Tu medicina, eh... Hablaremos de eso mañana.",
  ui_story_31170401_85_dialog_content = "Por ahora, ¿por qué no te metes en la ducha y duermes un poco más?",
  ui_story_31170401_86_dialog_content = "Bueno, me siento bastante cansado... Entonces, iré a hacer eso, Gram.",
  ui_story_31170401_87_dialog_content = "Buenos dias, PlayerName!",
  ui_story_31170401_88_dialog_content = "¡Hola, Vice! ¡Buenos días!",
  ui_story_31170401_89_dialog_content = "Te levantaste temprano hoy, PlayerName. ¿Te sientes mejor?",
  ui_story_31170401_90_dialog_content = "Buenos días, Gram.",
  ui_story_31170401_91_dialog_content = "Sí, ¡mucho mejor! Cuando me levanté esta mañana, me sentí tan despierto y lleno de energía. ¡No creo que necesite tomar ninguna medicina hoy!",
  ui_story_31170401_92_dialog_content = "Los jóvenes se recuperan muy rápido... ¡Parece que mi cura funcionó, después de todo!",
  ui_story_31170401_93_dialog_content = "¿Ah?",
  ui_story_31170401_94_dialog_content = "En resumen, tomaste tu medicina ayer. ¿Entiendes?",
  ui_story_31170401_95_option_content = "Entiendo.",
  ui_story_31170401_96_dialog_content = "Esas pruebas de ayer, eran tanto trabajo como ejercicios, ¿no?",
  ui_story_31170401_97_dialog_content = "Y cuando nos sentamos a comer... eso fue alrededor de la hora de la cena, ¿no?",
  ui_story_31170401_98_dialog_content = "Cansado y lleno, me quedé dormido en cuanto me acosté en la cama... y dormí durante ocho horas completas.",
  ui_story_31170401_99_dialog_content = "Eso significa que, <color=#FFB400>la mejor cura es el ejercicio regular y una buena rutina diaria</color>!",
  ui_story_31170401_100_option_content = "Realmente no...",
  ui_story_31170401_101_dialog_content = "(Ejem) ¿Recuerdas a qué hora cenaste?",
  ui_story_31170401_102_dialog_content = "Creo que fue tarde en la tarde...",
  ui_story_31170401_103_dialog_content = "Esas pruebas que hiciste durante el día... en realidad eran solo trabajo físico.",
  ui_story_31170401_104_dialog_content = "Agrega una cena saludable y un buen descanso nocturno, ¡y volverás a ser tú mismo!",
  ui_story_31170401_105_dialog_content = "Ya veo... ¡Ahora lo entiendo! <color=#FFB400>La mejor cura es el ejercicio regular y una buena rutina diaria</color>.",
  ui_story_31170401_106_dialog_content = "¡Así es!",
  ui_story_31170401_107_dialog_content = "¡Gracias, Gram!",
  ui_story_31170401_108_dialog_content = "Me alegra que te sientas mejor. Recuerda que tu cuerpo es tu responsabilidad, pero no olvides que otras personas también cuentan contigo.",
  ui_story_31170401_109_dialog_content = "Especialmente en lo que respecta a la batalla. Por el bien de tus amigos, no puedes permitir que tu cuerpo vuelva a ese estado. ¿Entendido?",
  ui_story_31170401_110_option_content = "¡Entendido!",
  ui_story_31170401_111_dialog_content = "Si me permito estar tan cansado y débil, podría afectar seriamente mi capacidad para dar órdenes.",
  ui_story_31170401_112_dialog_content = "En ese caso, incluso el más pequeño error podría costarte caro. El precio incluso podría tener que pagarse en sangre...",
  ui_story_31170401_113_dialog_content = "Tienes razón... ¡Me cuidaré mejor de ahora en adelante!",
  ui_story_31170401_114_option_content = "¿Pero por qué?",
  ui_story_31170401_115_dialog_content = "Tú estás a cargo de dirigirnos en batalla, ¿recuerdas?",
  ui_story_31170401_116_dialog_content = "Si algo sale mal... Es posible que...",
  ui_story_31170401_117_dialog_content = "Podría tener consecuencias graves.",
  ui_story_31170401_118_dialog_content = "Entiendo ahora. No dejaré que vuelva a ese estado nunca más.",
  ui_story_31170401_119_dialog_content = "Mientras entiendas.",
  ui_story_31170401_120_dialog_content = "Ahora bien, ya que estás curado y bien, creo que es hora de que me despida.",
  ui_story_31170401_121_dialog_content = "Se fue tan rápido... Ni siquiera tuve la oportunidad de agradecerle adecuadamente.",
  ui_story_31170401_122_dialog_content = "Gram no es del tipo que acepta gratitud así. Mientras te sientas mejor, eso es más que suficiente para él.",
  ui_story_31170401_123_dialog_content = "No dejes que su actitud despreocupada te engañe. Está extremadamente atento al bienestar de sus amigos.",
  ui_story_31170401_124_dialog_content = "El <color=#FFB400>Arroz Frito del Soldado</color> que hizo para ti ayer es su mejor plato. ¡Está lleno de nutrientes y además es súper saludable!",
  ui_story_31170401_125_dialog_content = "Así que así se llama... ¡Estaba tan delicioso! No creo que olvide nunca el sabor...",
  ui_story_31170401_126_dialog_content = "Antes de que él cocinara ese plato para mí, pensaba que Gram era simplemente un veterano común que trabajaba como gerente de logística.",
  ui_story_31170401_127_dialog_content = "Tiene una historia tan larga y llena de acontecimientos... Cuando se unió por primera vez al ejército, trabajó como cocinero durante unos años antes de pasar a la línea defensiva para repeler los ataques de los Eclipsites...",
  ui_story_31170401_128_dialog_content = "Después de retirarse del ejército, comenzó a trabajar en logística, donde también redescubrió su amor por la cocina. Todos esos años de experiencia y entrenamiento... ¡Es increíble!",
  ui_story_31170401_129_dialog_content = "Pero su Arroz Frito del Soldado está reservado para los enfermos. También lo he probado solo una vez en mi vida.",
  ui_story_31170401_130_dialog_content = "Incluso pensé en quedarme despierto hasta tarde los próximos días, solo para que él me lo hiciera de nuevo...",
  ui_story_31170401_131_dialog_content = "¿Crees que vale la pena, PlayerName?",
  ui_story_31170401_132_dialog_content = "Yo-yo no lo creo...",
  ui_story_31170401_133_dialog_content = "El Arroz Frito del Soldado podría saber increíble, pero esas pruebas fueron demasiado agotadoras...",
  ui_story_31170601_1_dialog_content = "<color=#e8d9bb>Splish, chapoteo—</color>",
  ui_story_31170601_2_dialog_content = "No, solo espera! Aún no bajo—",
  ui_story_31170601_3_dialog_content = "<size=45>No voy a caer—¡Aaaaahhh!</size>",
  ui_story_31170601_4_dialog_content = "<size=45>¡NOOOO—</size>",
  ui_story_31170601_5_dialog_content = "<size=45>¡Aaaaahhh—!</size>",
  ui_story_31170601_6_dialog_content = "<color=#e8d9bb>Hace quince minutos</color>",
  ui_story_31170601_7_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_8_dialog_content = "Oh, qué aire refrescante. Hace mucho tiempo que no venía a un valle tan sereno y hermoso.",
  ui_story_31170601_9_dialog_content = "Pero, ¿es nuestro destino final? Pensé que era entrenamiento, ¿o...?",
  ui_story_31170601_10_dialog_content = "¿Por fin muestras compasión y aprovechas la oportunidad para llevarme a hacer turismo?",
  ui_story_31170601_11_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_31170601_12_dialog_content = "¿Gram?!",
  ui_story_31170601_13_dialog_content = "¿D-Dónde estás? ¿No te caíste accidentalmente al lago, verdad? ¡No me asustes así!",
  ui_story_31170601_14_dialog_content = "Sabes, el nombre Gram y \"caer accidentalmente\" no deberían estar en la misma oración. ¿Por qué no te unes a mí?",
  ui_story_31170601_15_dialog_content = "¿Eh? ¡Espera, no, no me jales al agua—!",
  ui_story_31170601_16_dialog_content = "Abre los ojos y mira, chico. Ni siquiera llega a las rodillas.",
  ui_story_31170601_17_dialog_content = "Tienes razón... Jaja, es agradable jugar en el agua así de vez en cuando.",
  ui_story_31170601_18_dialog_content = "Sabía que te gustaría.",
  ui_story_31170601_19_dialog_content = "Pero no te confundas, este es nuestro campo de entrenamiento natural.",
  ui_story_31170601_20_dialog_content = "¿Ves esa cascada? ¡Ve a pararte en ella!",
  ui_story_31170601_21_dialog_content = "¿Qué tipo de entrenamiento es este?",
  ui_story_31170601_22_dialog_content = "Como soldado de primera línea, debes mantenerte tranquilo y resistir hasta el final, sin importar lo que se te presente.",
  ui_story_31170601_23_dialog_content = "Mantener tu postura bajo la cascada que fluye rápidamente sin moverte es la mejor manera de perfeccionar esa disciplina.",
  ui_story_31170601_24_dialog_content = "Llamo al entrenamiento, \"Los guerreros nunca caen.\"",
  ui_story_31170601_25_dialog_content = "Es una batalla contra la naturaleza, así como entre tú y yo.",
  ui_story_31170601_26_dialog_content = "Ven, PlayerName! Quien se levante primero será el responsable de cocinar hoy.",
  ui_story_31170601_27_dialog_content = "¿Qué? ¡Pero he estado deseando probar tu comida y por eso acepté el entrenamiento!",
  ui_story_31170601_28_dialog_content = "Entonces, ¿no crees que tengas ninguna posibilidad de vencerme?",
  ui_story_31170601_29_option_content = "¡De alguna manera me daré una oportunidad!",
  ui_story_31170601_30_dialog_content = "Tengo que creer que hay una oportunidad, por pequeña que sea. De lo contrario, ¡no podré vencerte en absoluto!",
  ui_story_31170601_31_option_content = "¡Eso es porque eres demasiado duro para mí!",
  ui_story_31170601_32_dialog_content = "Aun así, tengo que intentarlo.",
  ui_story_31170601_33_dialog_content = "¡Probaré tu cocina!",
  ui_story_31170601_34_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_35_dialog_content = "¡Ahh! El impacto es mayor de lo que pensaba...",
  ui_story_31170601_36_dialog_content = "Casi... estoy en mi límite...",
  ui_story_31170601_37_dialog_content = "No, just hang on! I'm not going down yet—",
  ui_story_31170601_38_dialog_content = "<size=45>Not going down—Aaaaahhh!</size>",
  ui_story_31170601_39_dialog_content = "<size=45>NOOOO—</size>",
  ui_story_31170601_40_dialog_content = "<size=45>Aaaaahhh—</size>",
  ui_story_31170601_41_dialog_content = "<size=45><color=#e8d9bb>¡Chapoteo!</color></size>",
  ui_story_31170601_42_dialog_content = "Jajaja! No está mal, chico, te mantuviste mucho más tiempo del que esperaba.",
  ui_story_31170601_43_dialog_content = "(¿Cómo puede Gram seguir de pie como una pared en la cascada después de tanto tiempo?)",
  ui_story_31170601_44_dialog_content = "(Suspiro, era de esperarse, en realidad. Ni siquiera estoy en la misma liga que él...)",
  ui_story_31170601_45_dialog_content = "¡Muy bien, la cena está en tus manos ahora!",
  ui_story_31170601_46_dialog_content = "Este entrenamiento es demasiado difícil para mí. Es imposible para mí ganar sin las ventajas físicas y de fuerza que tú tienes.",
  ui_story_31170601_47_dialog_content = "PlayerName, has estado en el frente de Illumina, así que sabes que tenemos tipos flacos en el ejército.",
  ui_story_31170601_48_dialog_content = "Y cuando lucharon, lo hicieron tan bien como yo. ¿Sabes por qué?",
  ui_story_31170601_49_dialog_content = "... Sí, Gram, entiendo a lo que te refieres. No pondré más excusas.",
  ui_story_31170601_50_dialog_content = "Siempre encuentras la fuente de un problema en el menor tiempo posible, por eso acepté llevarte a entrenar.",
  ui_story_31170601_51_dialog_content = "Desde que me convertí en instructor, he tenido la oportunidad de ver a más y más jóvenes de calidad.",
  ui_story_31170601_52_dialog_content = "A cambio, haré exigencias más difíciles que antes, ¡así que será mejor que traigas tu mejor esfuerzo!",
  ui_story_31170601_53_dialog_content = "Casi olvido que ahora eres el instructor para los nuevos reclutas.",
  ui_story_31170601_54_dialog_content = "No es de extrañar que haya algo diferente en ti... ¿Qué ha estado pasando?",
  ui_story_31170601_55_dialog_content = "¿Estás interesado?",
  ui_story_31170601_56_dialog_content = "Entonces ve a preparar la cena ahora. Asegúrate de hacer la prueba de acondicionamiento físico que te mostré antes.",
  ui_story_31170601_57_dialog_content = "¿Prueba de acondicionamiento físico? ¿Te refieres a la rutina de ejercicio antes de cocinar?",
  ui_story_31170601_58_dialog_content = "No puedo escapar de tu régimen incluso cuando pierdo, ya veo...",
  ui_story_31170601_59_dialog_content = "<color=#e8d9bb>Some time later</color>",
  ui_story_31170601_60_dialog_content = "*eructo*",
  ui_story_31170601_61_dialog_content = "No esperaba que probar comida deliciosa en la naturaleza fuera tan placentero.",
  ui_story_31170601_62_dialog_content = "Es un doble disfrute a nivel espiritual y físico que solo obtienes después de poner todo tu esfuerzo en el entrenamiento.",
  ui_story_31170601_63_dialog_content = "Entonces, ¿qué tal si sales conmigo más a menudo?",
  ui_story_31170601_64_dialog_content = "Con eso, realmente quieres decir que salga y entrene contigo, ¿verdad?",
  ui_story_31170601_65_dialog_content = "Oh, cierto, Gram, hablando de eso, ¿sucedió algo interesante?",
  ui_story_31170601_66_dialog_content = "Te he contado lo que más se me quedó grabado en la cabeza. En cuanto al resto...",
  ui_story_31170601_67_dialog_content = "Los superiores actualizaron el equipo regular de todos nuevamente. Revy se fue a su propia misión. Ansia finalmente descubrió el interruptor del altavoz...",
  ui_story_31170601_68_dialog_content = "Y yo, llegué a comprender la elección que Brent hizo.",
  ui_story_31170601_69_dialog_content = "Ver a todos estos jóvenes que conozco crecer tan rápido se siente bien. Estoy más feliz y orgulloso que ganar una batalla.",
  ui_story_31170601_70_dialog_content = "Aunque a veces recibía malas noticias y tenía que asistir a algunos entierros.",
  ui_story_31170601_71_dialog_content = "Ver los nombres de los soldados que entrené en las lápidas me hace dudar si debería seguir siendo instructor.",
  ui_story_31170601_72_dialog_content = "En mi caso o en el de Brent, nosotros, los gruñones, vivimos lo suficiente como para no tener ningún arrepentimiento al sacrificarnos.",
  ui_story_31170601_73_dialog_content = "Pero cada uno de los nuevos reclutas es tan limpio como una sábana nueva.",
  ui_story_31170601_74_dialog_content = "Simplemente no puedo soportar ver a esos jóvenes perder sus vidas... Ya sabes, Brent me regañaría por pensar así.",
  ui_story_31170601_75_dialog_content = "Pero, ¿qué puedes hacer además de ser duro y aún más duro cuando los entreno?",
  ui_story_31170601_76_dialog_content = "Convierte a los novatos en guerreros antes de que lleguen al campo de batalla para que no tengan que hacer sacrificios innecesarios.",
  ui_story_31170601_77_dialog_content = "Ya veo que tenías buenas intenciones... Pero, ¿has considerado volver al frente?",
  ui_story_31170601_78_dialog_content = "Con lo invencible e indomable que eres, puedes convertirte fácilmente en un modelo a seguir para los soldados, ¡e incluso en una figura a la altura de los comandantes!",
  ui_story_31170601_79_dialog_content = "Está bien. Juré hace mucho tiempo terminar lo que Brent no pudo. Y...",
  ui_story_31170601_80_dialog_content = "\"Los guerreros nunca caen\" no significa un soldado siempre invencible e indomable.",
  ui_story_31170601_81_dialog_content = "Pero ¿no eres uno tú mismo?",
  ui_story_31170601_82_dialog_content = "Soy un auroriano mortal con mis propias debilidades también. Realmente no existen guerreros invencibles e indomables.",
  ui_story_31170601_83_dialog_content = "Pero \"los guerreros nunca caen\" no es un lema que uso para engañarte.",
  ui_story_31170601_84_dialog_content = "La pequeña imagen es que quizás miles y miles de guerreros caerán finalmente en batalla.",
  ui_story_31170601_85_dialog_content = "¡Pero en el panorama general, habrá miles y miles más para ocupar su lugar!",
  ui_story_31170601_86_dialog_content = "¡Eso es lo que realmente significa \"los guerreros nunca caen\"!",
  ui_story_31170601_87_dialog_content = "Vaya, te volviste muy profundo rápidamente...",
  ui_story_31170601_88_dialog_content = "Probablemente sea porque llevas un tiempo entrenando a personas.",
  ui_story_31170601_89_dialog_content = "Sí, y hay algo en lo que he estado pensando desde hace bastante tiempo...",
  ui_story_31170601_90_dialog_content = "Debes perfeccionar tanto tus atributos físicos como tus habilidades psíquicas al mismo tiempo.",
  ui_story_31170601_91_dialog_content = "E-Eso suena difícil...",
  ui_story_31170601_92_dialog_content = "¡Pero no hay problema! Si me caigo, simplemente me levantaré de nuevo, ya que...",
  ui_story_31170601_93_dialog_content = "¡Guerreros! ¡Nunca! ¡Caer!",
  ui_story_31170601_94_dialog_content = "Jajaja, ¡muy bien! Aprendes rápido, ¡niño!"
}
return config
